import{az as s,P as a,Q as n,aQ as e}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"ITCSS（Inverted Triangle CSS）","description":"","frontmatter":{},"headers":[],"relativePath":"css/进阶/ITCSS.md","filePath":"css/进阶/ITCSS.md","lastUpdated":1785249401000}'),o={name:"css/进阶/ITCSS.md"};function d(r,t,l,c,p,i){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="itcss-inverted-triangle-css" tabindex="-1">ITCSS（Inverted Triangle CSS） <a class="header-anchor" href="#itcss-inverted-triangle-css" aria-label="Permalink to “ITCSS（Inverted Triangle CSS）”">​</a></h1><p>ITCSS 即&quot;倒三角 CSS&quot;，由 Harry Roberts 提出，是一种按<strong>特异性和明确性递增</strong>的顺序组织 CSS 的架构方法论。</p><h2 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to “核心思想”">​</a></h2><p>CSS 的整体结构呈倒三角形：底层是最通用、最宽泛的样式，越往上越具体。每一层只依赖下层，避免特异性混乱和样式覆盖冲突。</p><h2 id="七层结构" tabindex="-1">七层结构 <a class="header-anchor" href="#七层结构" aria-label="Permalink to “七层结构”">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>前缀</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>Settings</strong></td><td>—</td><td>变量、配置</td><td><code>$primary-color: #1890ff;</code></td></tr><tr><td><strong>Tools</strong></td><td>—</td><td>Sass 混合宏、工具函数</td><td><code>@mixin clearfix {}</code></td></tr><tr><td><strong>Generic</strong></td><td>—</td><td>重置样式、基础盒模型</td><td><code>normalize.css</code>、<code>box-sizing</code></td></tr><tr><td><strong>Elements</strong></td><td>—</td><td>裸 HTML 元素样式</td><td><code>h1 { font-size: 2rem; }</code></td></tr><tr><td><strong>Objects</strong></td><td><code>.o-</code></td><td>无装饰的 OOCSS 对象</td><td><code>.o-layout</code>、<code>.o-media</code></td></tr><tr><td><strong>Components</strong></td><td><code>.c-</code></td><td>具体的 UI 组件</td><td><code>.c-button</code>、<code>.c-card</code></td></tr><tr><td><strong>Trumps</strong></td><td><code>.u-</code></td><td>工具类/覆盖类</td><td><code>.u-hidden</code>、<code>.text-center</code></td></tr></tbody></table><h2 id="示意图" tabindex="-1">示意图 <a class="header-anchor" href="#示意图" aria-label="Permalink to “示意图”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>         ▲</span></span>
<span class="line"><span>        / \\</span></span>
<span class="line"><span>       /   \\    Trumps（特异性最高，最具体）</span></span>
<span class="line"><span>      /  c  \\   Components</span></span>
<span class="line"><span>     /   o   \\  Objects</span></span>
<span class="line"><span>    /    e    \\ Elements</span></span>
<span class="line"><span>   /     g     \\ Generic</span></span>
<span class="line"><span>  /      t      \\ Tools</span></span>
<span class="line"><span> /       s       \\ Settings（最宽泛）</span></span>
<span class="line"><span>/─────────────────\\</span></span></code></pre></div><h2 id="命名前缀规范" tabindex="-1">命名前缀规范 <a class="header-anchor" href="#命名前缀规范" aria-label="Permalink to “命名前缀规范”">​</a></h2><table tabindex="0"><thead><tr><th>前缀</th><th>含义</th><th>用途</th></tr></thead><tbody><tr><td><code>.o-</code></td><td>Object</td><td>布局对象，无装饰，可复用</td></tr><tr><td><code>.c-</code></td><td>Component</td><td>具体 UI 组件</td></tr><tr><td><code>.u-</code></td><td>Utility</td><td>工具类，单一职责</td></tr><tr><td><code>.is-</code> / <code>.has-</code></td><td>State</td><td>状态类（如 <code>.is-active</code>）</td></tr><tr><td><code>._</code></td><td>Hack</td><td>临时补丁，需注释说明</td></tr></tbody></table><h2 id="与-bem-的关系" tabindex="-1">与 BEM 的关系 <a class="header-anchor" href="#与-bem-的关系" aria-label="Permalink to “与 BEM 的关系”">​</a></h2><p>ITCSS 解决<strong>文件放哪层</strong>的问题，BEM 解决<strong>类名怎么起</strong>的问题。两者配合使用：</p><div class="language-scss"><button title="Copy Code" class="copy"></button><span class="lang">scss</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">// ITCSS 的 Components 层</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// BEM 命名规范</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">c-card</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#FFCB6B;">  &amp;</span><span style="color:#89DDFF;">__title</span><span style="color:#89DDFF;"> {</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#FFCB6B;">  &amp;</span><span style="color:#89DDFF;">__content</span><span style="color:#89DDFF;"> {</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#FFCB6B;">  &amp;</span><span style="color:#BABED8;">--large </span><span style="color:#89DDFF;">{</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to “实践建议”">​</a></h2><ol><li><strong>严格按层引入</strong>：确保 Settings 在最前，Trumps 在最后</li><li><strong>不跨层覆盖</strong>：Component 层不要覆盖其他 Component，需要调整时用 Trumps</li><li><strong>控制 Trumps 数量</strong>：工具类过多会导致 HTML 臃肿，优先用 Component</li></ol>`,15)])])}const b=s(o,[["render",d]]);export{m as __pageData,b as default};
